import java.util.*;

public class Main {
    static int n, t;
    static class Point {
        int row, col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
    static class Edge {
        int node, cap;
        Edge(int node, int cap) {
            this.node = node;
            this.cap = cap;
        }
    }
    static int[] d_x = {-1, 0, 1, 0, 0};
    static int[] d_y = {0, 1, 0, -1, 0};

    static boolean valid(int x, int y) {
        return (x >= 0 && x < n && y >= 0 && y < n);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        String[] first_map = new String[n];
        String[] second_map = new String[n];
        for (int i = 0; i < n; i++) {
            first_map[i] = sc.next();
        }
        for (int i = 0; i < n; i++) {
            second_map[i] = sc.next();
        }

        int[][] dist = new int[n][n];
        for (int[] row : dist)
            Arrays.fill(row, 1000);
        Point start_point = null;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (first_map[i].charAt(j) == 'Z') {
                    start_point = new Point(i, j);
                }
            }
        }
        Queue<Point> q = new LinkedList<>();
        dist[start_point.row][start_point.col] = 0;
        q.offer(start_point);
        while (!q.isEmpty()) {
            Point curr = q.poll();
            for (int dir = 0; dir < 4; dir++) {
                int nx = curr.row + d_x[dir];
                int ny = curr.col + d_y[dir];
                if (valid(nx, ny) && first_map[nx].charAt(ny) >= '0' && first_map[nx].charAt(ny) <= '9' && dist[nx][ny] == 1000) {
                    dist[nx][ny] = dist[curr.row][curr.col] + 1;
                    q.offer(new Point(nx, ny));
                }
            }
        }

        boolean[][][][][] can_reach = new boolean[60][10][10][10][10];
        for (int i = 0; i < 60; i++)
            for (int j = 0; j < 10; j++)
                for (int k = 0; k < 10; k++)
                    for (int l = 0; l < 10; l++)
                        for (int m = 0; m < 10; m++)
                            can_reach[i][j][k][l][m] = false;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 4; k++) {
                    int l = i + d_x[k], m = j + d_y[k];
                    if (valid(l, m) && first_map[i].charAt(j) >= '0' && first_map[i].charAt(j) <= '9' && first_map[l].charAt(m) >= '0' && first_map[l].charAt(m) <= '9') {
                        can_reach[0][i][j][l][m] = true;
                    }
                }
            }
        }

        for (int step = 0; step <= t - 2; step++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (!can_reach[step][i][j][k][l]) continue;
                            for (int o = 0; o < 4; o++) {
                                int p = k + d_x[o], r = l + d_y[o];
                                if (valid(p, r) && first_map[p].charAt(r) >= '0' && first_map[p].charAt(r) <= '9' && dist[k][l] >= step + 2 && dist[p][r] >= step + 2) {
                                    can_reach[step + 1][i][j][p][r] = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        List<Point> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (first_map[i].charAt(j) >= '0' && first_map[i].charAt(j) <= '9') {
                    points.add(new Point(i, j));
                }
            }
        }

        int total_nodes = 2 * points.size() + 2;
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < total_nodes; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < points.size(); i++) {
            int capacityStart = first_map[points.get(i).row].charAt(points.get(i).col) - '0';
            int capacityEnd = second_map[points.get(i).row].charAt(points.get(i).col) - '0';

            // Source to node
            graph.get(0).add(new Edge(i + 1, capacityStart));
            // Node to source (reverse edge)
            graph.get(i + 1).add(new Edge(0, 0));

            // Node to sink
            graph.get(points.size() + 1 + i).add(new Edge(total_nodes - 1, capacityEnd));
            // Sink to node (reverse edge)
            graph.get(total_nodes - 1).add(new Edge(points.size() + 1 + i, 0));
        }

        for (int i = 0; i < points.size(); i++) {
            for (int j = 0; j < points.size(); j++) {
                boolean reachableFlag = false;
                for (int k = 0; k <= t - 1; k++) {
                    if (can_reach[k][points.get(i).row][points.get(i).col][points.get(j).row][points.get(j).col]) {
                        reachableFlag = true;
                        break;
                    }
                }
                if (reachableFlag) {
                    // Add edge from i+1 to points.size()+1+j
                    graph.get(i + 1).add(new Edge(points.size() + 1 + j, 1000));
                    // Add reverse edge
                    graph.get(points.size() + 1 + j).add(new Edge(i + 1, 0));
                }
            }
        }

        int flow_value = 0;
        while (true) {
            boolean[] visited = new boolean[total_nodes];
            int[] parent = new int[total_nodes];
            Arrays.fill(parent, -1);
            Queue<Integer> q2 = new LinkedList<>();
            visited[0] = true;
            q2.offer(0);
            while (!q2.isEmpty()) {
                int u = q2.poll();
                for (Edge e : graph.get(u)) {
                    if (!visited[e.node] && e.cap > 0) {
                        visited[e.node] = true;
                        parent[e.node] = u;
                        q2.offer(e.node);
                    }
                }
            }
            if (parent[total_nodes - 1] == -1) break;

            int min_cap = Integer.MAX_VALUE;
            for (int v = total_nodes - 1; v != 0; v = parent[v]) {
                int u = parent[v];
                for (Edge e : graph.get(u)) {
                    if (e.node == v && e.cap > 0) {
                        min_cap = Math.min(min_cap, e.cap);
                        break;
                    }
                }
            }

            flow_value += min_cap;
            for (int v = total_nodes - 1; v != 0; v = parent[v]) {
                int u = parent[v];
                for (Edge e : graph.get(u)) {
                    if (e.node == v) {
                        e.cap -= min_cap;
                        break;
                    }
                }
                for (Edge e : graph.get(v)) {
                    if (e.node == u) {
                        e.cap += min_cap;
                        break;
                    }
                }
            }
        }

        System.out.println(flow_value);
        sc.close();
    }
}
